const label=(en,ko)=>`<span data-i18n-en="${esc(en)}" data-i18n-ko="${esc(ko)}">${esc(en)}</span>`;
function writable(f,g){return !!g&&!g.remoteReadOnly&&data.gangs.includes(g)&&g.fighters.includes(f);}
